    <div id="root"></div>

    <script>
      const faqItems = [
        {
          question: "How often should I feed my cat?",
          answer:
            "Most adult cats do well with two measured meals per day, while kittens need smaller meals more often. Your cat's age, activity level, and health needs should guide exact portions, so use the food label as a starting point and adjust with your veterinarian's advice."
        },
        {
          question: "Why does my cat knead blankets or people?",
          answer:
            "Kneading is a comforting behavior cats learn as kittens while nursing. Adult cats often knead when they feel safe, relaxed, or affectionate, especially on soft surfaces that remind them of cozy resting spots."
        },
        {
          question: "Do indoor cats still need playtime?",
          answer:
            "Yes. Indoor cats need daily play to exercise their bodies and satisfy hunting instincts. Short sessions with wand toys, puzzle feeders, or chase games can reduce boredom and support a healthy weight."
        },
        {
          question: "How can I tell if my cat is stressed?",
          answer:
            "Common signs include hiding, over-grooming, appetite changes, litter box accidents, aggression, or unusual vocalizing. Sudden behavior changes can also point to medical issues, so persistent symptoms deserve a vet check."
        },
        {
          question: "What is the best way to introduce a new cat?",
          answer:
            "Go slowly. Start the new cat in a separate room, swap scents with bedding, feed both cats near opposite sides of a closed door, and move to brief supervised visits only when both seem calm."
        }
      ];

      function Header() {
        return `
          <section class="hero" aria-labelledby="page-title">
            <div class="hero-card">
              <p class="eyebrow">Cat companion guide</p>
              <h1 id="page-title">FAQ for curious cat people.</h1>
              <p class="intro">
                Quick, practical answers for keeping cats healthy, comfortable,
                and happily entertained at home.
              </p>
            </div>
            <aside class="stats-card" aria-label="Cat care highlight">
              <div class="cat-icon" aria-hidden="true">🐾</div>
              <div>
                <h2>Small routines make confident cats.</h2>
                <p>
                  Predictable meals, clean litter, enrichment, and calm handling
                  help cats feel secure in their territory.
                </p>
              </div>
            </aside>
          </section>
        `;
      }

      function FAQItem(item, index) {
        const answerId = `answer-${index}`;
        return `
          <div class="example">
            <button
              class="question-button"
              type="button"
              aria-expanded="false"
              aria-controls="${answerId}"
            >
              <span class="question-text">${item.question}</span>
              <span class="chevron" aria-hidden="true">
                <svg width="18" height="18" viewBox="0 0 20 20" fill="none">
                  <path d="M5 7.5L10 12.5L15 7.5" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/>
                </svg>
              </span>
            </button>
            <div class="answer" id="${answerId}">
              <div class="answer-inner">
                <p>${item.answer}</p>
              </div>
            </div>
          </div>
        `;
      }

      function FAQList(items) {
        return `
          <section class="details" aria-label="Frequently asked questions">
            ${items.map(FAQItem).join("")}
          </section>
        `;
      }

      function App() {
        return `
          <main class="page-shell">
            ${Header()}
            ${FAQList(faqItems)}
          </main>
        `;
      }

      document.querySelector("#root").innerHTML = App();

      document.querySelectorAll(".example").forEach((example) => {
        const button = example.querySelector(".question-button");

        button.addEventListener("click", () => {
          const isOpen = example.classList.toggle("is-open");
          button.setAttribute("aria-expanded", String(isOpen));
        });
      });
    </script>
  </body>
</html>
