    <title>Cat Care FAQ</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f6f8fb;
        --card: #ffffff;
        --text: #172033;
        --muted: #667085;
        --line: #e6eaf0;
        --brand: #6d5dfc;
        --brand-dark: #4f46e5;
        --accent: #fff3d6;
        --shadow: 0 24px 70px rgba(24, 31, 50, 0.12);
